import requests
import json

# Test USAspending award endpoint to see if SIN data is available
url = 'https://api.usaspending.gov/api/v2/search/spending_by_award/'
payload = {
    'filters': {
        'psc_codes': ['7030'],
        'time_period': [{'start_date': '2024-10-01', 'end_date': '2025-09-30'}]
    },
    'fields': ['Award ID', 'Recipient Name', 'Award Amount', 'generated_internal_id', 'Contract IDV PIID', 'NAICS Code', 'PSC Code'],
    'page': 1,
    'limit': 5
}
r = requests.post(url, json=payload, timeout=30)
print('Status:', r.status_code)
if r.status_code == 200:
    data = r.json()
    for award in data.get('results', []):
        print(json.dumps(award, indent=2))
        print('---')

import requests
import json

# Test USAspending award endpoint with simpler filters
url = 'https://api.usaspending.gov/api/v2/search/spending_by_award/'
payload = {
    'filters': {
        'psc_codes': ['7030']
    },
    'fields': ['Award ID', 'Recipient Name', 'Award Amount', 'generated_internal_id'],
    'page': 1,
    'limit': 3
}
r = requests.post(url, json=payload, timeout=30)
print('Status:', r.status_code)
if r.status_code == 200:
    data = r.json()
    for award in data.get('results', []):
        print(json.dumps(award, indent=2))
        print('---')
else:
    print(r.text[:500])
